parameters.jsCode:
// Normalize Grafana's webhook payload into a flat per-alert list.
//
// Grafana posts: { receiver, status, alerts:[{status,labels,annotations,startsAt,endsAt,values,generatorURL,silenceURL,dashboardURL,panelURL,fingerprint}], groupLabels, commonLabels, commonAnnotations, externalURL, version, groupKey, truncatedAlerts, orgId, title, message }.
// We fan out one item per alert so downstream nodes (Slack, email) can format independently.

const body = $input.first().json.body || $input.first().json;
const alerts = Array.isArray(body.alerts) ? body.alerts : [];
const externalURL = body.externalURL || '';

if (alerts.length === 0) {
  return [{ json: { skip: true, reason: 'No alerts in payload', raw: body } }];
}

return alerts.map((a) => {
  const labels = a.labels || {};
  const annotations = a.annotations || {};
  // Severity convention: alert rule labels.severity ∈ {info, warning, critical}.
  const severity = (labels.severity || 'info').toLowerCase();
  const isFiring = (a.status || 'firing') === 'firing';
  return {
    json: {
      alertName: labels.alertname || annotations.summary || 'Grafana alert',
      status: a.status,
      isFiring,
      isResolved: !isFiring,
      severity,
      summary: annotations.summary || '',
      description: annotations.description || annotations.message || '',
      runbookUrl: annotations.runbook_url || '',
      labels,
      annotations,
      startsAt: a.startsAt,
      endsAt: a.endsAt,
      values: a.values || {},
      generatorURL: a.generatorURL || '',
      silenceURL: a.silenceURL || '',
      dashboardURL: a.dashboardURL || '',
      panelURL: a.panelURL || '',
      externalURL,
      fingerprint: a.fingerprint || '',
    },
  };
});

