    {
      "type": "header",
      "text": {
        "type": "plain_text",
        "text": "{{ $json.isFiring ? '\ud83d\udea8 CRITICAL' : '\u2705 RESOLVED' }}: {{ $json.alertName }}",
        "emoji": true
      }
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*{{ $json.summary }}*\n{{ $json.description }}"
      }
    },
    {
      "type": "context",
      "elements": [
        { "type": "mrkdwn", "text": "Severity: {{ $json.severity }} | Started: {{ $json.startsAt }}" }
      ]
    },
    {
      "type": "actions",
      "elements": [
        { "type": "button", "text": { "type": "plain_text", "text": "View in Grafana" }, "url": "{{ $json.generatorURL || $json.externalURL }}" },
        { "type": "button", "text": { "type": "plain_text", "text": "Silence" }, "url": "{{ $json.silenceURL }}" }
      ]
    }
  ]
}

